package com.infoviaan.basic.IfElse;

public class CheckVovelOrConsonant {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		char ch = 'h';
		
		if(ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u') {
			System.out.println("Entred Alphabet is Vovel");
		}else {
			System.out.println("Entred Alphabet is Consonant");
		}

	}

}
